47		// virtual switch (WSL2 NAT mode only): set by withWSL.
48		WindowsHost bool
49	}
50	
51	const (
52		sourceLabel       = "this machine"
53		routeUndetermined = "undetermined"
54		gatewayDirect     = "directly connected"
55	)
56	
57	// newPathRoute converts a route lookup into a pathRoute. A failed lookup
58	// discards whatever the hop holds. Addresses are unmapped to IPv4 when they can be.
59	func newPathRoute(hop netcheck.RouteHop, err error) pathRoute {
60		if err != nil {
61			return pathRoute{}
62		}
63		return pathRoute{
64			Known:     true,
65			Interface: hop.Interface,
66			Source:    addrFromIP(hop.Source),
67			Gateway:   addrFromIP(hop.Gateway),
68		}
69	}
70	
71	// addrFromIP returns ip as an unmapped netip.Addr, or the zero Addr for a nil or invalid ip.
72	func addrFromIP(ip net.IP) netip.Addr {
73		addr, ok := netip.AddrFromSlice(ip)
74		if !ok {
75			return netip.Addr{}
76		}
77		return addr.Unmap()
78	}
79	
80	// pathSteps returns the rows of the Path column: the source, then the
81	// interface and gateway when route is not nil, then the hops as selected by
82	// visiblePathHops. It returns nil while neither a route nor a hop exists.
83	// Neither input is modified.
84	func pathSteps(ctr *pathContainer, route *pathRoute, hops []nettrace.Hop) []pathStep {
85		if ctr == nil && route == nil && len(hops) == 0 {
86			return nil
87		}
88		var steps []pathStep
89		if ctr != nil {
90			steps = append(steps,
