107		}
108		if ctr != nil {
109			steps = append(steps, pathStep{Kind: stepTrace, Container: *ctr})
110		}
111		for _, h := range visiblePathHops(hops) {
112			steps = append(steps, pathStep{Kind: stepHop, Hop: h})
113		}
114		return steps
115	}
