1	package netdiag
2	
3	import (
4		"context"
5		"fmt"
6		"log"
7		"net"
8		"net/netip"
9		"time"
10	
11		tea "charm.land/bubbletea/v2"
12	
13		"github.com/anthnel/devdesk/internal/docker"
14		"github.com/anthnel/devdesk/internal/engine"
15		"github.com/anthnel/devdesk/internal/netcheck"
16		"github.com/anthnel/devdesk/internal/netiface"
17		"github.com/anthnel/devdesk/internal/nettrace"
18		"github.com/anthnel/devdesk/internal/wslenv"
19	)
20	
21	// pathChanCap holds a whole trace: every hop (at most MaxHopsLimit), the
22	// resolved message and the done message. The producer therefore never waits
23	// for a reader. Contract: resolved now carries source and ctr but is still one
24	// message, so 1 resolved + MaxHopsLimit (30) hops + 1 done = 32 = pathChanCap,
25	// and sendDone never evicts resolved with the real engine.
26	const pathChanCap = nettrace.MaxHopsLimit + 2
27	
28	// pathEngine is the seam between the path tab and the network: tests replace
29	// it with a fake.
30	type pathEngine struct {
31		supported func() error
32		resolve   func(ctx context.Context, host string) ([]netip.Addr, error)
33		route     func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error)
34		trace     func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error)
35	
36		engineName func() string                                                            // engine.Current().Name
37		engineOS   func(ctx context.Context) (string, error)                                // docker.EngineOperatingSystem
38		running    func(ctx context.Context) ([]docker.Container, error)                    // running containers only
39		inspect    func(ctx context.Context, id string) (docker.ContainerNetworking, error) // read-only
40		network    func(ctx context.Context, id string) (docker.NetworkBridge, error)       // docker.InspectNetworkBridge
41		interfaces func(ctx context.Context) ([]netiface.Interface, error)                  // netiface.List
42		platform   func(ctx context.Context) wslenv.Info                                    // wslenv.Detect; nil means not WSL2
43	}
44	
45	// systemPathEngine returns the engine backed by the real resolver and sockets.
46	func systemPathEngine() pathEngine {
47		env := netcheck.SystemEnv(netcheck.DefaultSettings())
48		return pathEngine{
49			supported: systemPathSupport,
50			resolve: func(ctx context.Context, host string) ([]netip.Addr, error) {
51				return net.DefaultResolver.LookupNetIP(ctx, "ip4", host)
52			},
53			route: func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error) {
54				return env.Route(ctx, net.IP(a.AsSlice()))
55			},
56			trace:      nettrace.TraceEach,
57			engineName: func() string { return engine.Current().Name },
58			engineOS:   docker.EngineOperatingSystem,
59			running: func(ctx context.Context) ([]docker.Container, error) {
60				return docker.ListContainersContext(ctx, false)
61			},
62			inspect:    docker.InspectContainerNetworking,
63			network:    docker.InspectNetworkBridge,
64			interfaces: netiface.List,
65			platform:   wslenv.Detect,
66		}
67	}
68	
69	// pathResolvedMsg reports the address the target resolved to.
70	type pathResolvedMsg struct {
71		gen      int
72		addr     netip.Addr
73		route    netcheck.RouteHop
74		routeErr error
75		source   pathSource                 // the source at launch
76		ctr      docker.ContainerNetworking // zero for this machine
77		ctrErr   error                      // logged by the producer, never shown
78		bridge   pathBridge                 // what is known of the container network's host interface
79		platform wslenv.Info                // WSL2 detection for this launch; zero when not WSL2
80	}
81	
82	// pathSourcesMsg carries what the selector offers once the engine answered.
83	type pathSourcesMsg struct {
84		gen  int // the request it answers, so a stale answer can be dropped
85		list pathSourceList
86	}
87	
88	// loadPathSourcesCmd reads the selector's list off the Update goroutine, under
89	// its own timeout so a hung engine cannot keep the selector loading. It
90	// touches no model (Rule 110): the answer comes back as a message.
91	func loadPathSourcesCmd(gen int, timeout time.Duration, e pathEngine) tea.Cmd {
92		return func() tea.Msg {
93			return pathSourcesMsg{gen: gen, list: listPathSourcesUnder(context.Background(), timeout, e)}
94		}
95	}
96	
97	// listPathSourcesUnder reads the list under a timeout derived from parent.
98	// Only parent decides whether an error is logged: a deadline exceeded on its
99	// own is a real failure, a canceled parent is not.
100	func listPathSourcesUnder(parent context.Context, timeout time.Duration, e pathEngine) pathSourceList {
101		ctx, cancel := context.WithTimeout(parent, timeout)
102		defer cancel()
103		return readPathSources(parent, ctx, e)
104	}
105	
106	// listPathSources reads what the selector offers with a single context.
107	func listPathSources(ctx context.Context, e pathEngine) pathSourceList {
108		return readPathSources(ctx, ctx, e)
109	}
110	
111	// readPathSources reads what the selector offers. Only read-only engine calls
112	// are made (info, ps): nothing starts or enters a container. A raw error goes
113	// to the log, never to the note, unless parent was canceled.
114	func readPathSources(parent, ctx context.Context, e pathEngine) pathSourceList {
115		name := ""
116		if e.engineName != nil {
117			name = e.engineName()
118		}
119		if name != "docker" { // podman: no exec at all
120			return sourceListFrom(name, "", nil, nil, nil)
121		}
122		osName, osErr := e.engineOS(ctx)
123		if osErr != nil {
124			logSourcesError(parent, osErr)
125			return sourceListFrom(name, "", osErr, nil, nil)
126		}
127		if isDockerDesktop(osName) {
128			return sourceListFrom(name, osName, nil, nil, nil)
129		}
130		cs, psErr := e.running(ctx)
131		if psErr != nil {
132			logSourcesError(parent, psErr)
133		}
134		return sourceListFrom(name, osName, nil, cs, psErr)
135	}
136	
137	// logSourcesError logs a read failure unless the caller gave up (parent is
138	// the context received, not the one bounded by the timeout).
139	func logSourcesError(parent context.Context, err error) {
140		if parent.Err() == nil {
141			log.Printf("ERROR [netdiag/path] sources: %v", err)
142		}
143	}
144	
145	// pathHopMsg carries one hop as the engine reports it.
146	type pathHopMsg struct {
147		gen int
148		hop nettrace.Hop
149	}
150	
151	// pathDoneMsg ends a run: a result, or an error when no trace happened.
152	type pathDoneMsg struct {
153		gen    int
154		result nettrace.Result
155		err    error
156	}
157	
158	// producePath resolves the target, traces it and sends the messages to out,
159	// then closes out. It runs inside a Cmd and touches no model (Rule 110).
160	// out must have room for pathChanCap messages: sends never block, so a view
161	// that stops reading after canceling leaks nothing.
162	func producePath(ctx context.Context, gen int, tg pathTarget, src pathSource, resolveTimeout time.Duration, e pathEngine, out chan tea.Msg) {
163		defer close(out)
164		send := func(m tea.Msg) {
165			select {
166			case out <- m:
167			default:
168			}
169		}
170		// sendDone must never be lost: when the channel is full the oldest message
171		// is dropped to make room. The producer is the only sender, so one drop
172		// frees a slot for good.
173		sendDone := func(m tea.Msg) {
174			for range 2 {
175				select {
176				case out <- m:
177					return
178				default:
179				}
180				select {
181				case <-out:
182				default:
183				}
184			}
185		}
186	
187		addr, err := resolvePathTarget(ctx, tg.Host, resolveTimeout, e)
188		if err != nil {
189			if ctx.Err() == nil { // esc during the resolution is not an error
190				log.Printf("ERROR [netdiag/path] resolve %s: %v", tg.Host, err)
191			}
192			sendDone(pathDoneMsg{gen: gen, err: err})
193			return
194		}
195		// The route is asked for the address actually traced. A failure is not
196		// fatal and is never shown: the trace goes on without the route column.
197		route, routeErr := e.route(ctx, addr)
198		if routeErr != nil && ctx.Err() == nil {
199			log.Printf("ERROR [netdiag/path] route %s: %v", tg.Host, routeErr)
200		}
201		ctr, ctrErr := inspectPathSource(ctx, src, resolveTimeout, e)
202		var bridge pathBridge
203		if ctrErr == nil && !src.isHost() {
204			bridge = readPathBridge(ctx, ctr, resolveTimeout, e)
205		}
206		platform := detectPathPlatform(ctx, resolveTimeout, e)
207		send(pathResolvedMsg{gen: gen, addr: addr, route: route, routeErr: routeErr, source: src, ctr: ctr, ctrErr: ctrErr, bridge: bridge, platform: platform})
208	
209		res, err := e.trace(ctx, addr, nettrace.Options{}, func(h nettrace.Hop) {
210			send(pathHopMsg{gen: gen, hop: h})
211		})
212		if err != nil {
213			log.Printf("ERROR [netdiag/path] trace %s: %v", tg.Host, err)
214		}
215		sendDone(pathDoneMsg{gen: gen, result: res, err: err})
216	}
217	
218	// inspectPathSource reads the chosen container's network under its own
219	// timeout. This machine reads nothing. A failure is not fatal and is never
220	// shown: the raw error goes to the log unless the run was canceled.
221	func inspectPathSource(ctx context.Context, src pathSource, timeout time.Duration, e pathEngine) (docker.ContainerNetworking, error) {
222		if src.isHost() {
223			return docker.ContainerNetworking{}, nil
224		}
225		ictx, cancel := context.WithTimeout(ctx, timeout)
226		defer cancel()
227		ctr, err := e.inspect(ictx, src.ID)
228		if err != nil && ctx.Err() == nil {
229			log.Printf("ERROR [netdiag/path] inspect %s: %v", src.ID, err)
230		}
231		return ctr, err
232	}
233	
234	// detectPathPlatform asks the engine once whether this machine is WSL2, under
235	// its own timeout. No engine function means not WSL2.
236	func detectPathPlatform(ctx context.Context, timeout time.Duration, e pathEngine) wslenv.Info {
237		if e.platform == nil {
238			return wslenv.Info{}
239		}
240		pctx, cancel := context.WithTimeout(ctx, timeout)
241		defer cancel()
242		return e.platform(pctx)
243	}
244	
245	// resolvePathTarget returns the IPv4 address to trace: a literal is used as
246	// is, a name is resolved under its own timeout.
247	func resolvePathTarget(ctx context.Context, host string, timeout time.Duration, e pathEngine) (netip.Addr, error) {
248		if a, err := netip.ParseAddr(host); err == nil && a.Is4() {
249			return a, nil
250		}
251		rctx, cancel := context.WithTimeout(ctx, timeout)
252		defer cancel()
253		addrs, err := e.resolve(rctx, host)
254		if err != nil {
255			return netip.Addr{}, fmt.Errorf("%w: %w", errPathResolve, err)
256		}
257		if len(addrs) == 0 {
258			return netip.Addr{}, errPathNoIPv4
259		}
260		return addrs[0], nil
261	}
262	
263	// waitForPathMsg returns a Cmd that yields the next message of in, or nil
264	// once in is closed. The view re-arms it after every message.
265	func waitForPathMsg(in <-chan tea.Msg) tea.Cmd {
266		return func() tea.Msg {
267			m, ok := <-in
268			if !ok {
269				return nil
270			}
271			return m
272		}
273	}
